void matching_native_state() {
  Ocel input;
  const auto raw=bytes("00ffeda080");
  input.events={{"e0","A","later",{{raw,-0.0}}},{"e1","B","earlier",{{"dup",nullptr},{"dup",raw}}}};
  input.objects={{"o0","T",{{raw,std::numeric_limits<double>::quiet_NaN()}}},
                 {"unused","T",{{"dup",nullptr},{"dup",raw}}}};
  input.relations={{"e1","o0",raw},{"e0","o0","q"},{"e0","o0","q"}};
  input.o2o={{"o0","unused",raw},{"o0","o0",raw},{"o0","o0",raw}};
  input.e2e={{"e0","e1",raw},{"e0","e0",raw},{"e0","e0",raw}};
  input.object_changes={{"o0","T","later",raw,raw},{"unused","T","earlier",raw,-0.0}};
  input.globals={{raw,raw},{"zero",-0.0},{"missing",nullptr}};
  input.event_type_attributes={{"unused",{{raw,"string"}}}};
  input.object_type_attributes={{"unused",{{raw,"time"}}}};
  input.table_columns.events=std::vector<std::string>{raw,"dup","dup"};
  input.table_columns.objects=std::vector<std::string>{};
  input.table_columns.relations=std::nullopt;
  const auto before=serialize_oc_playout_workbench_ocel_json(input);
  auto expected=input;
  expected.events.resize(1);
  expected.objects.resize(1);
  expected.relations.erase(expected.relations.begin());
  expected.o2o.erase(expected.o2o.begin());
  expected.e2e.erase(expected.e2e.begin());
  expected.object_changes.resize(1);
  auto result=filter_ocel_activity_type_matching_exact(input,{{"T",{"A"}}});
  assert(serialize_oc_playout_workbench_ocel_json(result)==serialize_oc_playout_workbench_ocel_json(expected));
  result.events[0].attributes.clear(); result.globals[raw]=true;
  assert(serialize_oc_playout_workbench_ocel_json(input)==before);
  assert(filter_ocel_activity_type_matching_exact(input,{}).events.empty());
}
